   243→<script>
   244→import * as pdfjsLib from 'pdfjs-dist';
   245→pdfjsLib.GlobalWorkerOptions.workerSrc = '/pdf.worker.js';
   246→import { v4 as uuidv4 } from 'uuid'
   247→import { markRaw } from 'vue';
   248→
   249→export default {
   250→  props: {
   251→    file: {
   252→      type: [String, ArrayBuffer, Blob],
   253→      required: true,
   254→    },
   255→  },
   256→  data() {
   257→    return {
   258→      pdfCanvasWidth: 0,
   259→      pdfCanvasHeight: 0,
   260→      originalPdfWidth: 0,
   261→      originalPdfHeight: 0,
   262→      fields: [],
   263→      isRendering: false,
   264→      signatureCounter: 1,
   265→      renderingTask: null,
   266→      loadingPDF: false,
   267→      availableIds: [],
   268→      draggingField: null,
   269→      resizingField: null,
   270→      offsetX: 0,
   271→      offsetY: 0,
   272→      scrollX: 0,
   273→      scrollY: 0,
   274→      scale: 1.5,
   275→      currentScale: 1,
   276→      pdfPages: [],
   277→      currentPage: 1,
   278→      pdf: null,
   279→      selectedField: null,
   280→      showDuplicateDialog: false,
   281→      selectedFieldToDuplicate: null,
   282→      selectedDuplicatePage: null,
   283→      signerDataDialog: false,
   284→      editingField: null,
   285→    };
   286→  },
   287→  computed: {
   288→    filteredFields() {
   289→      if (!this.fields) return [];
   290→      return this.fields.filter(f => f.pageNumber === this.currentPage);
   291→    },
   292→
   293→    hasQrField() {
   294→      return this.fields.some(f => f.type === 'qr');
   295→    },
   296→
   297→    includeAllData: {
   298→      get() {
   299→        if (!this.editingField) return false;
   300→        return this.editingField.includeFullName && this.editingField.includeDocumentInfo;
   301→      },
   302→      set(newValue) {
   303→        if (this.editingField) {
   304→          this.editingField.includeFullName = newValue;
   305→          this.editingField.includeDocumentInfo = newValue;
   306→        }
   307→      }
   308→    }
   309→  },
   310→  watch: {
   311→    file: {
   312→      immediate: true,
   313→      handler(newFile) {
   314→        if (newFile) {
   315→          this.loadPDF(newFile);
   316→        }
   317→      },
   318→    },
   319→
   320→    'editingField.includeFullName'(newValue) {
   321→      if (newValue === true) {
   322→        this.enforceMinDataSize();
   323→      }
   324→    },
   325→
   326→    'editingField.includeDocumentInfo'(newValue) {
   327→      if (newValue === true) {
   328→        this.enforceMinDataSize();
   329→      }
   330→    },
   331→
   332→    fields: {
   333→      handler(newFields) {
   334→        this.$emit('update-fields', newFields);
   335→      },
   336→      deep: true,
   337→    },
   338→  },
   339→  methods: {
   340→    async loadPDF(file) {
   341→      this.loadingPDF = true;
   342→      try {
   343→        const fileReader = new FileReader();
   344→        const pdfData = await new Promise((resolve) => {
   345→          fileReader.onload = (e) => resolve(new Uint8Array(e.target.result));
   346→          fileReader.readAsArrayBuffer(file);
   347→        });
   348→
   349→        const loadingTask = pdfjsLib.getDocument({ data: pdfData });
   350→        this.pdf = markRaw(await loadingTask.promise);
   351→        this.pdfPages = Array.from({ length: this.pdf.numPages }, (_, i) => i + 1);
   352→        this.$nextTick(() => {
   353→          this.renderPage(this.currentPage);
   354→        });
   355→      } catch (error) {
   356→        console.error('Error loading PDF:', error);
   357→      }
   358→      this.loadingPDF = false;
   359→    },
   360→
   361→    async renderPage(pageNum, scaleOverride = null) {
   362→      try {
   363→        if (this.isRendering && this.renderingTask) {
   364→          try {
   365→            await this.renderingTask.cancel();
   366→          } catch (cancelErr) {
   367→            console.warn('No se pudo cancelar render anterior:', cancelErr);
   368→          }
   369→        }
   370→
   371→        this.isRendering = true;
   372→        this.renderingTask = null;
   373→
   374→        const canvas = this.$refs.pdfCanvas;
   375→        const container = this.$refs.pdfContainer;
   376→
   377→        if (!this.pdf || typeof this.pdf.getPage !== 'function') {
   378→          throw new Error('Documento PDF no válido o no cargado');
   379→        }
   380→
   381→        const page = await this.pdf.getPage(pageNum);
   382→        const originalViewport = page.getViewport({ scale: 1 });
   383→
   384→        this.originalPdfWidth = originalViewport.width;
   385→        this.originalPdfHeight = originalViewport.height;
   386→
   387→        const baseScale = scaleOverride ?? this.currentScale ?? 1;
   388→        const containerHeight = container.clientHeight - 32;
   389→        const computedScale = baseScale || (containerHeight / originalViewport.height);
   390→
   391→        this.currentScale = computedScale;
   392→
   393→        const dpr = window.devicePixelRatio || 1;
   394→        const viewport = page.getViewport({ scale: computedScale * dpr });
   395→
   396→        canvas.width = viewport.width;
   397→        canvas.height = viewport.height;
   398→        canvas.style.width = `${viewport.width / dpr}px`;
   399→        canvas.style.height = `${viewport.height / dpr}px`;
   400→
   401→        const context = canvas.getContext('2d');
   402→        const renderTask = page.render({ canvasContext: context, viewport });
   403→        this.renderingTask = renderTask;
   404→
   405→        await renderTask.promise;
   406→
   407→        this.renderingTask = null;
   408→
   409→        this.$nextTick(() => {
   410→          const rect = canvas.getBoundingClientRect();
   411→          this.pdfCanvasWidth = rect.width;
   412→          this.pdfCanvasHeight = rect.height;
   413→        });
   414→
   415→      } catch (err) {
   416→        console.error('Error al renderizar página:', err);
   417→      }
   418→
   419→      this.isRendering = false;
   420→    },
   421→
   422→    zoomIn() {
   423→      const newScale = this.currentScale + 0.2;
   424→      this.renderPage(this.currentPage, newScale);
   425→    },
   426→
   427→    zoomOut() {
   428→      const newScale = this.currentScale - 0.2;
   429→      if (newScale > 0.1) {
   430→        this.renderPage(this.currentPage, newScale);
   431→      }
   432→    },
   433→
   434→    prevPage() {
   435→      if (this.currentPage > 1 && !this.isRendering) {
   436→        this.currentPage--;
   437→        this.renderPage(this.currentPage);
   438→      }
   439→    },
   440→
   441→    nextPage() {
   442→      if (this.currentPage < this.pdfPages.length && !this.isRendering) {
   443→        this.currentPage++;
   444→        this.renderPage(this.currentPage);
   445→      }
   446→    },
   447→
   448→    addSignatureField() {
   449→      let availableId = this.availableIds.length > 0
   450→        ? this.availableIds.shift()
   451→        : this.signatureCounter++;
   452→
   453→      const uniqueId = uuidv4();
   454→
   455→      const newField = {
   456→        id: uniqueId,
   457→        instanceId: uniqueId,
   458→        name: `[$FIRMA${availableId}]`,
   459→        type: 'signature',
   460→        top: 20,
   461→        left: 50,
   462→        width: 200,
   463→        height: 100,
   464→        pageNumber: this.currentPage,
   465→        includeFullName: true,
   466→        includeDocumentInfo: true,
   467→      };
   468→
   469→      this.fields.push(newField);
   470→    },
   471→
   472→    addQrField() {
   473→      if (this.hasQrField) return;
   474→
   475→      const uniqueId = uuidv4();
   476→
   477→      const newField = {
   478→        id: uniqueId,
   479→        instanceId: uniqueId,
   480→        name: 'Código QR',
   481→        type: 'qr',
   482→        top: 50,
   483→        left: 50,
   484→        width: 100,
   485→        height: 100,
   486→        pageNumber: this.currentPage,
   487→      };
   488→
   489→      this.fields.push(newField);
   490→    },
   491→
   492→    openSignerDataDialog(field) {
   493→      this.editingField = field;
   494→      this.signerDataDialog = true;
   495→    },
   496→
   497→    closeSignerDataDialog() {
   498→      this.signerDataDialog = false;
   499→      setTimeout(() => {
   500→        this.editingField = null;
   501→      }, 300);
   502→    },
   503→
   504→    deleteField(instanceId) {
   505→      const fieldToRemove = this.fields.find(field => field.instanceId === instanceId);
   506→
   507→      if (fieldToRemove) {
   508→        if (fieldToRemove.type === 'signature') {
   509→          const fieldNumber = parseInt(fieldToRemove.name.match(/\d+/)?.[0], 10);
   510→          if (!isNaN(fieldNumber)) {
   511→            this.availableIds.push(fieldNumber);
   512→            this.availableIds.sort((a, b) => a - b);
   513→          }
   514→        }
   515→
   516→        this.fields = this.fields.filter(field => field.instanceId !== instanceId);
   517→      }
   518→    },
   519→
   520→    openDuplicateDialog(field) {
   521→      this.selectedFieldToDuplicate = field;
   522→      this.selectedDuplicatePage = this.currentPage;
   523→      this.showDuplicateDialog = true;
   524→    },
   525→
   526→    confirmDuplicateField() {
   527→      if (!this.selectedFieldToDuplicate || !this.selectedDuplicatePage) return;
   528→
   529→      const original = this.selectedFieldToDuplicate;
   530→      const newField = {
   531→        ...original,
   532→        id: uuidv4(),
   533→        instanceId: uuidv4(),
   534→        pageNumber: this.selectedDuplicatePage,
   535→        top: original.top + 0.05,
   536→        left: original.left + 0.05,
   537→      };
   538→
   539→      newField.top = Math.min(newField.top, 0.9);
   540→      newField.left = Math.min(newField.left, 0.9);
   541→
   542→      this.fields.push(newField);
   543→      this.showDuplicateDialog = false;
   544→    },
   545→
   546→    checkCollision(rect1, rect2) {
   547→      return (
   548→        rect1.left < rect2.left + rect2.width &&
   549→        rect1.left + rect1.width > rect2.left &&
   550→        rect1.top < rect2.top + rect2.height &&
   551→        rect1.top + rect1.height > rect2.top
   552→      );
   553→    },
   554→
   555→    startDrag(event, field) {
   556→      event.preventDefault();
   557→
   558→      this.draggingField = field;
   559→
   560→      const wrapperRect = this.$refs.pdfContainer.querySelector('.pdf-wrapper').getBoundingClientRect();
   561→      this.offsetX = event.clientX - (field.left * this.currentScale + wrapperRect.left);
   562→      this.offsetY = event.clientY - (field.top * this.currentScale + wrapperRect.top);
   563→
   564→      this.boundOnDrag = (e) => this.onDrag(e);
   565→      this.boundStopDrag = () => this.stopDrag();
   566→
   567→      document.addEventListener('mousemove', this.boundOnDrag);
   568→      document.addEventListener('mouseup', this.boundStopDrag);
   569→    },
   570→
   571→    onDrag(event) {
   572→      if (!this.draggingField) return;
   573→
   574→      event.preventDefault();
   575→
   576→      const wrapperRect = this.$refs.pdfContainer.querySelector('.pdf-wrapper').getBoundingClientRect();
   577→      let newLeft = (event.clientX - this.offsetX - wrapperRect.left) / this.currentScale;
   578→      let newTop = (event.clientY - this.offsetY - wrapperRect.top) / this.currentScale;
   579→
   580→      const maxLeft = this.originalPdfWidth - this.draggingField.width;
   581→      const maxTop = this.originalPdfHeight - this.draggingField.height;
   582→
   583→      newLeft = Math.max(0, Math.min(newLeft, maxLeft));
   584→      newTop = Math.max(0, Math.min(newTop, maxTop));
   585→
   586→      const potentialRect = {
   587→        left: newLeft,
   588→        top: newTop,
   589→        width: this.draggingField.width,
   590→        height: this.draggingField.height
   591→      };
   592→
   593→      const hasCollision = this.filteredFields.some(field => {
   594→        if (field.instanceId === this.draggingField.instanceId) return false;
   595→        return this.checkCollision(potentialRect, field);
   596→      });
   597→
   598→      if (!hasCollision) {
   599→        this.draggingField.left = newLeft;
   600→        this.draggingField.top = newTop;
   601→      }
   602→    },
   603→
   604→    stopDrag() {
   605→      document.removeEventListener('mousemove', this.boundOnDrag);
   606→      document.removeEventListener('mouseup', this.boundStopDrag);
   607→
   608→      this.boundOnDrag = null;
   609→      this.boundStopDrag = null;
   610→
   611→      this.draggingField = null;
   612→    },
   613→
   614→    startResize(event, field) {
   615→      event.stopPropagation();
   616→      this.resizingField = field;
   617→      document.addEventListener('mousemove', this.onResize);
   618→      document.addEventListener('mouseup', this.stopResize);
   619→    },
   620→
   621→    onResize(event) {
   622→      if (!this.resizingField) return;
   623→
   624→      const canvasRect = this.$refs.pdfCanvas.getBoundingClientRect();
   625→      const scaleX = canvasRect.width / this.originalPdfWidth;
   626→      const scaleY = canvasRect.height / this.originalPdfHeight;
   627→
